#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-03
"""Ground truth for the entity layer: what `ros2 node info` reported at the
system-stable instant (snapshot/node_info_all.json, an independent source:
the ROS graph API, not the trace) versus what the model extracted from the
trace.  Per kind and per node: both / only ros2 (model missed) / only model
(ros2 missed, e.g. intra-process waitables are not graph entities).

usage: ground_truth_check.py <session_id> [scope] [--show N]"""
import collections, json, os, re, sys
import psycopg2
DSN = os.environ.get('FISH_PG_DSN', 'host=localhost port=5432 dbname=fish user=fish password=fish')
sid = sys.argv[1]; scope = sys.argv[2] if len(sys.argv) > 2 and not sys.argv[2].startswith('--') else '__main__'
show = int(sys.argv[sys.argv.index('--show') + 1]) if '--show' in sys.argv else 8
sdir = f'/home/tue037807/fish_traces/{sid}/snapshot'

# ---- ros2 node info
SECTIONS = {'Subscribers:': 'sub', 'Publishers:': 'pub', 'Service Servers:': 'serv',
            'Service Clients:': 'cli', 'Action Servers:': 'act_srv', 'Action Clients:': 'act_cli'}
ros = collections.defaultdict(lambda: collections.defaultdict(set))
for name, text in json.load(open(f'{sdir}/node_info_all.json')).items():
    cur = None
    for line in text.splitlines():
        s = line.strip()
        if s in SECTIONS:
            cur = SECTIONS[s]; continue
        if cur and ':' in s and s.startswith('/'):
            ros[name][cur].add(s.split(':', 1)[0].strip())

# ---- model
c = psycopg2.connect(DSN).cursor()
c.execute("SELECT node_id, full_name, attrs, children FROM graph_nodes WHERE session_id=%s AND scope=%s AND type='N'", (sid, scope))
nodes = c.fetchall()
c.execute("SELECT node_id, etype, label FROM graph_nodes WHERE session_id=%s AND scope=%s AND type='E'", (sid, scope))
E = {r[0]: (r[1], r[2]) for r in c.fetchall()}
model = collections.defaultdict(lambda: collections.defaultdict(set))
def topics_of(x):
    out = set()
    for p in (x or []):
        if isinstance(p, str): out.add(p)
        elif isinstance(p, dict): out.add(p.get('topic') or p.get('service') or p.get('name') or '')
        elif isinstance(p, (list, tuple)) and p: out.add(str(p[0]))
    out.discard(''); return out
for nid, full, attrs, children in nodes:
    m = model[full]
    m['pub'] |= topics_of(attrs.get('publishers'))
    m['cli'] |= topics_of(attrs.get('service_clients'))
    for cid in (children or []):
        et, lab = E.get(cid, (None, None))
        if et == 'sub': m['sub'].add(lab)
        elif et == 'serv': m['serv'].add(lab)
        elif et == 'cli': m['cli'].add(lab)
        elif et == 'waitable' and lab and '/_action/' in lab: m['act_srv'].add(lab.rsplit('/_action/', 1)[0])
        if lab and '/_action/' in lab and et in ('serv',): m['act_srv'].add(lab.rsplit('/_action/', 1)[0])
        if lab and '/_action/' in lab and et in ('cli',): m['act_cli'].add(lab.rsplit('/_action/', 1)[0])
    # action names in ros2 node info are the base names; drop the per-component service labels
    for k in ('serv', 'cli'):
        m[k] = {x for x in m[k] if '/_action/' not in x}

ros_nodes, model_nodes = set(ros), set(model)
print(f'nodes: ros2 node info {len(ros_nodes)}, model {len(model_nodes)}, both {len(ros_nodes & model_nodes)}, '
      f'only ros2 {len(ros_nodes - model_nodes)}, only model {len(model_nodes - ros_nodes)}')
for n in sorted(ros_nodes - model_nodes)[:show]: print('   only ros2 :', n)
for n in sorted(model_nodes - ros_nodes)[:show]: print('   only model:', n)
print()
tot = collections.defaultdict(collections.Counter); miss = collections.defaultdict(list); extra = collections.defaultdict(list)
for n in sorted(ros_nodes & model_nodes):
    for k in ('sub', 'pub', 'serv', 'cli', 'act_srv', 'act_cli'):
        a, b = ros[n][k], model[n][k]
        tot[k]['both'] += len(a & b); tot[k]['only_ros2'] += len(a - b); tot[k]['only_model'] += len(b - a)
        for x in sorted(a - b): miss[k].append((n, x))
        for x in sorted(b - a): extra[k].append((n, x))
print(f"{'kind':<8}{'both':>7}{'only ros2':>11}{'only model':>12}{'recall':>8}{'precision':>11}")
for k in ('sub', 'pub', 'serv', 'cli', 'act_srv', 'act_cli'):
    t = tot[k]; both, r, m = t['both'], t['only_ros2'], t['only_model']
    rec = both / (both + r) if both + r else float('nan'); pre = both / (both + m) if both + m else float('nan')
    print(f'{k:<8}{both:>7}{r:>11}{m:>12}{rec:>8.3f}{pre:>11.3f}')
for k in ('sub', 'pub', 'serv', 'cli'):
    if miss[k]:
        print(f'\n{k}: model missed (first {show} of {len(miss[k])}):')
        for n, x in miss[k][:show]: print(f'   {n}  {x}')
    if extra[k]:
        print(f'{k}: only in model (first {show} of {len(extra[k])}):')
        for n, x in extra[k][:show]: print(f'   {n}  {x}')
